cssSyntax.relativeCode:
/* Lighter by 10 percentage points of lightness */
color: oklch(from var(--brand) calc(l + 0.1) c h);

/* Shifted 30 degrees around the wheel */
color: oklch(from var(--brand) l c calc(h + 30));

/* Desaturated to 60% of its original chroma */
color: oklch(from var(--brand) l calc(c * 0.6) h);

/* Fully transparent version of the same color */
color: oklch(from var(--brand) l c h / 0%);

